@@ -1,6 +1,48 @@
 export type Query = Record<string, string | string[]>;
+
+function decodePart(s: string): string {
+  s = s.replace(/\+/g, " ");
+  try {
+    return decodeURIComponent(s);
+  } catch {
+    return s;
+  }
+}

 /** Parse a URL query string. See README.md for the rules. */
 export function parseQuery(query: string): Query {
-  throw new Error("not implemented");
+  const q = query.replace(/^\?/, "");
+  if (q === "") return {};
+
+  const result: Record<string, string | string[]> = {};
+
+  for (const rawPair of q.split("&")) {
+    if (rawPair === "") continue;
+
+    const eqIdx = rawPair.indexOf("=");
+    let key: string, value: string;
+    if (eqIdx === -1) {
+      key = rawPair;
+      value = "";
+    } else {
+      key = rawPair.slice(0, eqIdx);
+      value = rawPair.slice(eqIdx + 1);
+    }
+
+    key = decodePart(key);
+    value = decodePart(value);
+
+    if (Object.hasOwn(result, key)) {
+      const prev = result[key];
+      if (Array.isArray(prev)) {
+        prev.push(value);
+      } else {
+        result[key] = [prev, value];
+      }
+    } else {
+      result[key] = value;
+    }
+  }
+
+  return result;
 }
